"""Per-file inventory of an agent project's ``@tool`` functions.

:func:`inspect_project_tools` imports every tool module the runtime would
import — ``skills/<id>/tools.py``, ``skills/<id>/tools/*.py`` and the shared
agent-root ``tools/*.py`` — the same way :mod:`rasa.mantle.tools.loader` does,
and reports the tools each file defines plus the files that would fail a model
load. Unlike the loader it does not stop at the first broken file, so an
editor can show every problem at once.
"""

from __future__ import annotations

import uuid
from pathlib import Path
from typing import Callable, Iterator, List, Optional, Tuple

from pydantic import BaseModel, ConfigDict

from rasa.mantle.llm.tool_schemas import FRAMEWORK_TOOL_NAMES
from rasa.mantle.snapshot_lib import evict_snapshot_lib_modules
from rasa.mantle.tools.loader import (
    TOOLS_DIR_NAME,
    TOOLS_FILE_NAME,
    ToolLoadingError,
    _load_tool_module,
)
from rasa.shared.project_structure import MANTLE_SKILL_FILE, MANTLE_SKILLS_DIR

# ``load_shared_tools`` drops shared tools with this prefix (with a warning)
# because it is reserved for a skill's auto-generated collect setter.
_SHARED_RESERVED_PREFIX = "set_"


class ToolEntry(BaseModel):
    """A ``@tool`` function and the file that defines it."""

    model_config = ConfigDict(frozen=True)

    name: str
    description: str
    path: str
    skill_id: Optional[str]


class ToolFileError(BaseModel):
    """A tool file that would fail a model load."""

    model_config = ConfigDict(frozen=True)

    path: str
    message: str


class ToolInventory(BaseModel):
    """The tools found in a project and the files that could not be loaded."""

    model_config = ConfigDict(frozen=True)

    tools: List[ToolEntry]
    errors: List[ToolFileError]


def _tool_files(project_root: Path) -> Iterator[Tuple[Path, Optional[str]]]:
    """Yield ``(module_path, skill_id)`` for every tool module the loader imports.

    ``skill_id`` is ``None`` for shared agent-root tools.
    """
    skills_root = project_root / MANTLE_SKILLS_DIR
    if skills_root.is_dir():
        for skill_dir in sorted(p for p in skills_root.iterdir() if _is_skill(p)):
            single_file = skill_dir / TOOLS_FILE_NAME
            if single_file.is_file():
                yield single_file, skill_dir.name
            yield from (
                (path, skill_dir.name)
                for path in _dir_modules(skill_dir / TOOLS_DIR_NAME)
            )
    yield from ((path, None) for path in _dir_modules(project_root / TOOLS_DIR_NAME))


def _is_skill(skill_dir: Path) -> bool:
    """Return whether the skill catalog loads *skill_dir* as a skill.

    ``_``-prefixed dirs are private/scratch and a dir without ``skill.md`` is
    not a skill, so the runtime never imports their tools.
    """
    return (
        skill_dir.is_dir()
        and not skill_dir.name.startswith("_")
        and (skill_dir / MANTLE_SKILL_FILE).is_file()
    )


def _dir_modules(tools_dir: Path) -> List[Path]:
    if not tools_dir.is_dir():
        return []
    return [p for p in sorted(tools_dir.glob("*.py")) if p.name != "__init__.py"]


def _import_error_message(exc: ToolLoadingError) -> str:
    # The ``ToolLoadingError`` text embeds the absolute module path; the
    # underlying exception is what the author needs to see.
    return str(exc.__cause__) if exc.__cause__ is not None else str(exc)


def inspect_project_tools(project_root: Path) -> ToolInventory:
    """Import every tool module in *project_root* and report tools and failures.

    Each file is imported on its own, with the project root on ``sys.path``
    exactly as at train time, so one broken file does not hide the others.
    A file that defines a reserved framework tool name is reported as an
    error, since it fails a model load the same way an import error does.

    Imports run arbitrary project code and touch process-wide import state
    (``sys.path`` and the ``lib`` modules); callers that inspect projects
    concurrently must serialize calls.

    Args:
        project_root: The agent project directory (parent of ``skills/``).

    Returns:
        The tools sorted by name, and one error per failing file.
    """
    project_root = Path(project_root)
    module_prefix = f"_mantle_tool_inventory_{uuid.uuid4().hex}"
    tools: List[ToolEntry] = []
    errors: List[ToolFileError] = []

    evict_snapshot_lib_modules()
    try:
        for index, (module_path, skill_id) in enumerate(_tool_files(project_root)):
            relative_path = module_path.relative_to(project_root).as_posix()
            try:
                funcs = _load_tool_module(
                    module_path, f"{module_prefix}_{index}", project_root
                )
            except ToolLoadingError as exc:
                errors.append(
                    ToolFileError(
                        path=relative_path, message=_import_error_message(exc)
                    )
                )
                continue
            except SystemExit as exc:
                errors.append(
                    ToolFileError(
                        path=relative_path,
                        message=f"Module called sys.exit({exc.code!r}) on import.",
                    )
                )
                continue

            reserved = sorted(name for name in funcs if name in FRAMEWORK_TOOL_NAMES)
            if reserved:
                errors.append(
                    ToolFileError(
                        path=relative_path,
                        message=(
                            f"Defines tool(s) {reserved} that reuse reserved "
                            "framework tool names. Rename them — reserved names "
                            f"are: {sorted(FRAMEWORK_TOOL_NAMES)}."
                        ),
                    )
                )
            tools.extend(
                _entry(name, func, relative_path, skill_id)
                for name, func in funcs.items()
                if name not in FRAMEWORK_TOOL_NAMES
                and not (skill_id is None and name.startswith(_SHARED_RESERVED_PREFIX))
            )
    finally:
        # Do not leave this project's ``lib`` modules behind for the next load.
        evict_snapshot_lib_modules()

    tools.sort(key=lambda entry: (entry.name, entry.path))
    return ToolInventory(tools=tools, errors=errors)


def _entry(name: str, func: Callable, path: str, skill_id: Optional[str]) -> ToolEntry:
    return ToolEntry(
        name=name,
        description=str(getattr(func, "_tool_description")),
        path=path,
        skill_id=skill_id,
    )
